<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('wf_workflow_builder') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_popup"
          :settings="settings"
          :settingType="activeDialog.setting"
          :appKey="activeDialog.appKey"
          :preferredAppKey="activeDialog.preferredAppKey"
          :manageCreate="activeDialog.manageCreate"
          :onConfirm="activeDialog.confirmHandler"
        />
        <f-toggle size="xs"
          v-model="user_settings[setting_name]"
          @update:model-value="(val: boolean) => { setWorkflowBuilder(val); }"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
import {
  WORKFLOW_SETTING_NAME,
  WORKFLOW_DOC_FLOW_KEY,
  saveSettingsImpl,
  setWorkflowBuilderImpl,
  onLoadingSettingsChange,
  configureCombinedWorkflowDialog,
} from './workflowBuilderHelpers';
import type { ActiveDialogState } from './workflowBuilderHelpers';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: [],
  components: {
    subscriptionDialog,
  },
  data() {
    return {
      setting_name: WORKFLOW_SETTING_NAME,
      settings: {} as Record<string, any>,
      activeDialog: {
        setting: WORKFLOW_SETTING_NAME,
        appKey: WORKFLOW_DOC_FLOW_KEY as string | string[],
        preferredAppKey: '',
        manageCreate: true,
        confirmHandler: null,
      } as ActiveDialogState,
    };
  },
  watch: {
    loading_settings: {
      handler(newVal: boolean, oldVal: boolean) {
        onLoadingSettingsChange(this, newVal, oldVal);
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { updateSetting } = settings_store;
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      updateSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
      show_popup: ref(false),
    };
  },
  methods: {
    async saveSettings(key: string, value: any) {
      await saveSettingsImpl(this, key, value);
    },
    async setWorkflowBuilder(val: boolean) {
      if (val) {
        configureCombinedWorkflowDialog(this);
      }
      await setWorkflowBuilderImpl(this, val);
    },
  },
});
</script>
<style lang="css" scoped>
.buttons {
  margin: auto;
  max-width: 40%;
}
</style>
