<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('idm_acl_updater') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[setting_name]"
          @update:model-value="(val: boolean) => { saveSettings(setting_name, val); }"
        />
      </div>
    </div>

    <template v-if="user_settings[setting_name] == true">
      <div class="settings-acl-content">
        <q-file
          class="s-field back-white"
          style="max-width: 250px;"
          v-model="ionfile"
          :label="$t('ion_mapping')"
          data-cy="ion-file"
          outlined
          dense
          max-files="1"
          @update:model-value="uploadIonFile"
        >
          <template v-slot:prepend>
            <q-icon name="attach_file" />
          </template>
          <q-icon v-if="ionapi != ''" name="star" />
        </q-file>

        <div class="settings-acl-table-wrapper">
          <DocBitsTable
            :rows="infor_acl_info"
            :columns="aclColumns"
            row-key="id"
            table-id="infor_acl_table"
            :features="{
              sorting: false,
              filtering: false,
              selection: false,
              bulkActions: false,
              rowActions: true,
              resizable: false,
              pagination: false,
              columnReorder: false,
              stickyLastColumn: true,
            }"
            :row-actions="rowActions"
            no-data-label="no_record_found"
            flat-style
            @row-action="handleRowAction"
          />
          <f-btn
            style="height: 28px; margin-top: 0.5rem;"
            :label="$t('add')"
            @click="show_acl_popup = true"
          />
        </div>
      </div>
    </template>
  </div>

  <q-dialog v-model="show_acl_popup">
    <addACLMappingVue
      @keydown.esc="show_acl_popup = false"
      @close="show_acl_popup = false"
    />
  </q-dialog>

  <q-inner-loading :showing="loading || loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import addACLMappingVue from 'src/pages/Settings/Components/Modules/popup/addACLMapping.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  el: '#app',
    props: [],
  components: {
    addACLMappingVue,
    DocBitsTable,
  },
  data() {
    return {
      setting_name: CONSTANTS.INFOR_ACL_UPDATER_SETTING,
      aclColumns: [
        { name: 'doctype', label: this.$t('Infor-Doctype'), field: 'doctype', align: 'left' },
        { name: 'pre_acl', label: this.$t('Old-ACL'), field: 'pre_acl', align: 'left' },
        { name: 'after_acl', label: this.$t('New-ACL'), field: 'after_acl', align: 'left' },
      ] as UnifiedTableColumn[],
      rowActions: [
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative' },
      ] as RowActionItem[],
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (
          newVal == false &&
          oldVal == true &&
          !this.user_settings[this.setting_name]
        ) {
          this.user_settings[this.setting_name] = false;
        }
      },
    },
  },
  mounted() {
    if (this.user_settings[this.setting_name] == true) {
      this.getAclInfo();
    }
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings, infor_acl_info, ionapi } =
      storeToRefs(settings_store);
    const {
      getAclInfo,
      createAclInitializer,
      createAclMapping,
      deleteAclSetting,
      deleteAclMapping,
      updateSetting,
    } = settings_store;
    return {
      user_settings,
      loading_settings,
      infor_acl_info,
      ionapi,
      ionfile: ref(),
      loading: ref(false),
      selection: ref([] as any),
      headerCheckbox: ref(false),
      headerFabIcon: ref(false),

      show_acl_popup: ref(false),

      getAclInfo,
      updateSetting,
      createAclMapping,
      deleteAclSetting,
      deleteAclMapping,
      createAclInitializer,
    };
  },
  methods: {
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        this.deleteAclMapping(row.id);
      }
    },
    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
      if (value == false) {
        await this.deleteAclSetting();
      }
    },

    async uploadIonFile() {
      let formdata = new FormData();
      formdata.append('ionapi', this.ionfile);
      try {
        await this.createAclInitializer(formdata);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
});
</script>

<style lang="scss" scoped>
.settings-acl-content {
  padding: 0.75rem 1rem;
}

.settings-acl-table-wrapper {
  margin-top: 1rem;
  max-height: 300px;
  overflow-y: auto;
}
</style>
