<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('doc_operator') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_popup"
          :settings="user_settings"
          :settingType="doc_operator_setting"
          :appKey="doc_operator"
          :onConfirm="handleSubscriptionConfirm"
        />
        <f-toggle size="xs"
          v-model="user_settings[doc_operator_setting]"
          @update:model-value="save"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
    import { storeToRefs } from 'pinia';
        import { defineComponent, ref } from 'vue';
    import { useSettingStore, useSubscriptionStore } from 'src/store/main';
    import { doc_operator_setting,CONSTANTS} from 'src/constants';
    import helperMixin from 'src/mixins/helperMixin.js';
    import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';

    export default defineComponent({
        el: '#app',
        mixins: [helperMixin],
        props: ['showSpinner'],
        components: {
            subscriptionDialog,
        },
        data() {
            return {
                doc_operator_setting,
                doc_operator: CONSTANTS.doc_operator,
            };
        },
        watch: {
            loading_settings: {
                handler: function (newVal, oldVal) {
                    if (newVal == true && oldVal == false) {
                        return;
                    }
                    this.initView();
                },
            },
        },
        mounted: function () {
            this.initView();
        },
        setup () {
            const settings_store = useSettingStore();
            const { user_settings, loading_settings } = storeToRefs(settings_store);
            const { updateSetting } = settings_store;
    
            return {
                user_settings,
                loading_settings,
                loading: ref(false),
                show_popup: ref(false),
                updateSetting,
            }
        },
        methods: {
            cleanupOnhide () {
                this.show_popup = false;
            },
            initView() {
                if (!this.user_settings[this.doc_operator_setting]) {
                    this.user_settings[this.doc_operator_setting] = false;
                }
            },
            save(value: any) {
                if (value){
                    // Revert the toggle first
                    this.user_settings[this.doc_operator_setting] = false;
                    this.show_popup = true;
                } else {
                    // Disabling - just save directly
                    this.handleSubscriptionConfirm(value);
                }
            },
            
            handleSubscriptionConfirm(value: any) {

                useSubscriptionStore().saveSubscriptionChange(
                    value,
                    this.doc_operator,
                    this.showNotification,
                    this.updateSetting,
                    this.showErrorToast,
                    this.showSuccessToast
                );
            },
        },
    });
</script>
