<template>
  <q-card class="acl-dialog">
    <q-card-section class="dialog-header">
      <span class="dialog-title">{{ $t('add_idm_acl_mapping') }}</span>
      <q-btn
        flat
        round
        dense
        icon="close"
        color="white"
        @click="cancelDialog"
      />
    </q-card-section>

    <q-card-section class="dialog-content">
      <q-input
        class="s-field dialog-field"
        outlined
        dense
        :label="$t('idm_doctype')"
        v-model="new_acl_map['doctype']"
      />
      <q-input
        class="s-field dialog-field"
        outlined
        dense
        :label="$t('idm_old_acl_status')"
        v-model="new_acl_map['pre_acl']"
      />
      <q-input
        class="s-field dialog-field"
        outlined
        dense
        :label="$t('idm_new_acl_status')"
        v-model="new_acl_map['after_acl']"
      />
    </q-card-section>

    <q-card-actions align="right" class="dialog-actions">
      <f-btn
        appearance="cancel"
        :label="$t('cancel')"
        @click="cancelDialog"
      />
      <f-btn
        @click="saveChanges"
        :label="$t('save')"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';

export default defineComponent({
    emits: ['close'],
  methods: {
    async saveChanges() {
      await this.createAclMapping(this.new_acl_map);
      this.new_acl_map = {};
      this.$emit('close');
    },
    cancelDialog() {
      this.new_acl_map = {};
      this.$emit('close');
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const apidata = storeToRefs(settings_store);
    const { createAclMapping } = settings_store;

    return {
      apidata,
      createAclMapping,
      new_acl_map: ref({} as any),
    };
  },
});
</script>

