<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('qr_code_extraction') }}</span>
      </div>
      <div class="settings-toggle-selects toggle-selects-md" v-if="user_settings[qr_code_extraction_setting]">
        <q-select
          dense
          outlined
          class="back-white"
          v-model="user_settings[qr_bar_code_type_for_extraction]"
          :options="supported_barcode_types"
          emit-value
          use-chips
          multiple
          map-options
          label="Select"
          @update:model-value="(val: any) => saveSettings(qr_bar_code_type_for_extraction, val)"
        />
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[qr_code_extraction_setting]"
          @update:model-value="(val: boolean) => saveSettings(qr_code_extraction_setting, val)"
        />
      </div>
    </div>
  </div>

  <q-inner-loading :showing="loading || loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { orgPreferenceApiService, userApiService } from 'src/services';
import {
  qr_code_extraction_setting,
  qr_bar_code_type_for_extraction,
} from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: [],
  components: {},
  data() {
    return {
      supported_barcode_types: ref([]),
      qr_code_extraction_setting,
      qr_bar_code_type_for_extraction,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.setDefaultValues();
        }
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { updateSetting } = settings_store;
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      updateSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
    };
  },
  mounted: function () {
    this.getBarCodeTypes();
    this.init();
    this.setDefaultValues();
  },
  methods: {
    init() {
      let value = this.user_settings[this.qr_bar_code_type_for_extraction];
      if (typeof value === 'string') {
        this.user_settings[this.qr_bar_code_type_for_extraction] = value
          .split(',')
          .map((v) => v.trim())
          .filter(Boolean);
      } else if (!Array.isArray(value)) {
        this.user_settings[this.qr_bar_code_type_for_extraction] = [];
      }
    },
    setDefaultValues() {
      if (!this.user_settings[this.qr_code_extraction_setting]) {
        this.user_settings[this.qr_code_extraction_setting] = false;
      }

      if (!this.user_settings[this.qr_bar_code_type_for_extraction]) {
        this.user_settings[this.qr_bar_code_type_for_extraction] = [];
      }
    },
    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
        logInfo(this.user_settings[key]);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async getBarCodeTypes() {
      this.showLoading();
      let response: any;

      try {
        response = await orgPreferenceApiService.getSupportedBarcodeTypes();

        if (
          !response ||
          typeof response !== 'object' ||
          Array.isArray(response)
        ) {
          throw { message: this.$t('invalid_barcode_type_response_format') };
        }
        // Convert object entries to dropdown-friendly format
        this.supported_barcode_types = Object.entries(response).map(
          ([key, value]) => ({
            value: key,
            label: value,
          }),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
});
</script>
