<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('inbound_emails') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[setting_name]"
          @update:model-value="(val: boolean) => { saveSettings(setting_name, val); }"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import { importApiService, userApiService } from 'src/services';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: [],
  components: {},
  data() {
    return {
      setting_name: CONSTANTS.INBOUND_EMAILS,
      api_key: ref(''),
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == false && oldVal == true) {
          if (!this.user_settings[this.setting_name]) {
            this.user_settings[this.setting_name] = false;
          }
        }
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { updateSetting } = settings_store;
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      updateSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
    };
  },
  methods: {
    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);
        const data = {
          app_key: 'FELLOW_DOC2',
        };
        const response = await userApiService.getAppSubscription(data);
        this.api_key = response[0].token;
        await importApiService.DeActivateinbound(
          getOrgId(),
          value,
          this.api_key,
        );
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>
