<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('barcode_assignment') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[barcode_assignment_setting]"
          @update:model-value="updatedBarcodeSetting"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { barcode_assignment_setting } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  el: '#app',
    props: ['showSpinner'],
  components: {},
  data() {
    return {
      barcode_assignment_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.barcode_assignment_setting]) {
        this.user_settings[this.barcode_assignment_setting] = false;
      }
    },
    async updatedBarcodeSetting(value: any) {
      try {
        await this.updateSetting(barcode_assignment_setting, value);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
  },
});
</script>
