<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('tasks_and_notifications') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[tasks_notification_setting]"
          @update:model-value="(val: any) => { handleTasksNotificationToggle(val); }"
        />
      </div>
    </div>
    <div class="settings-toggle-item" v-if="user_settings[tasks_notification_setting]">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('dashboard_tasks_count') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[dashboard_tasks_count_activated]"
          @update:model-value="(val: any) => { updateSetting(dashboard_tasks_count_activated, val); }"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import {
  tasks_notification_setting,
  dashboard_tasks_count_activated,
} from 'src/constants';

export default defineComponent({
  el: '#app',
    props: ['showSpinner'],
  components: {},
  data() {
    return {
      tasks_notification_setting,
      dashboard_tasks_count_activated,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  computed: {},
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.tasks_notification_setting]) {
        this.user_settings[this.tasks_notification_setting] = false;
      }

      if (!this.user_settings[this.dashboard_tasks_count_activated]) {
        this.user_settings[this.dashboard_tasks_count_activated] = false;
      }
    },
    handleTasksNotificationToggle(val: any) {
      this.updateSetting(this.tasks_notification_setting, val);
      if (!val && this.user_settings[this.dashboard_tasks_count_activated]) {
        this.user_settings[this.dashboard_tasks_count_activated] = false;
        this.updateSetting(this.dashboard_tasks_count_activated, false);
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
