<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('supplier_dashboard') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_popup"
          :settings="{}"
          :settingType="supplier_portal_setting"
          :appKey="CONSTANTS.supplier_portal"
          :onConfirm="handleSubscriptionConfirm"
        />
        <f-toggle size="xs"
          v-model="user_settings[supplier_dashboard_setting]"
          @update:model-value="saveSupplierPortal"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import {
  supplier_dashboard_setting,
  asn_dashboard_setting,
  supplier_portal_setting,
  CONSTANTS,
} from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
export default defineComponent({
  el: '#app',
    components: { subscriptionDialog },
  data() {
    return {
      CONSTANTS,
      supplier_dashboard_setting,
      supplier_portal_setting,
      asn_dashboard_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  computed: {},
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      show_popup: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.supplier_dashboard_setting]) {
        this.user_settings[this.supplier_dashboard_setting] = false;
      }

      if (!this.user_settings[this.asn_dashboard_setting]) {
        this.user_settings[this.asn_dashboard_setting] = false;
      }
    },
    saveSupplierPortal(value: any) {
      if (value) {
        this.user_settings[this.supplier_dashboard_setting] = false;
        this.show_popup = true;
      } else {
        this.handleSubscriptionConfirm(value);
      }
    },

    async handleSubscriptionConfirm(value: any) {
      try {
        await this.updateSetting(supplier_dashboard_setting, value);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
