<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('doc_scan') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_popup"
          :settings="{}"
          :settingType="setting_name"
          :appKey="CONSTANTS.doc_scan"
          :onConfirm="handleSubscriptionConfirm"
        />
        <f-toggle size="xs"
          v-model="user_settings[setting_name]"
          @update:model-value="saveDocScan"
        />
      </div>
    </div>
  </div>

  <q-inner-loading :showing="loading || loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
export default defineComponent({
  el: '#app',
    props: [],
  components: { subscriptionDialog },
  data() {
    return {
      CONSTANTS,
      setting_name: CONSTANTS.DOC_SCAN_MODULE_SETTING,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (
          newVal == false &&
          oldVal == true &&
          !this.user_settings[this.setting_name]
        ) {
          this.user_settings[this.setting_name] = false;
        }
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;
    return {
      user_settings,
      loading_settings,
      updateSetting,
      loading: ref(false),
      show_popup: ref(false),
    };
  },
  methods: {
    saveDocScan(value: any) {
      if (value) {
        this.user_settings[this.setting_name] = false;
        this.show_popup = true;
      } else {
        this.handleSubscriptionConfirm(value);
      }
    },

    handleSubscriptionConfirm(value: any) {
      this.saveSettings(this.setting_name, value);
    },

    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
