<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('bod_connection_stream') }}
          <q-icon name="info" class="cursor-pointer q-ml-xs" color="grey-6" size="xs">
            <q-tooltip>{{ $t('cloud_only_feature') }}</q-tooltip>
          </q-icon>
          <q-spinner-ios v-if="loading" size="16px" color="primary" class="q-ml-sm" />
        </span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="settings[bod_connection_stream_setting]"
          @update:model-value="(val: any) => { save(val); }"
          :disable="loading"
        />
      </div>
    </div>

    <template v-if="settings[bod_connection_stream_setting]">
      <div class="settings-toggle-item-with-selects">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('stream_name') }}</span>
        </div>
        <div class="settings-toggle-selects toggle-selects-md">
          <q-input
            outlined
            dense
            class="s-field back-white"
            v-model="stream_name"
            :readonly="true"
          >
            <template v-slot:append>
              <q-spinner-ios v-if="loading" size="16px" color="primary" />
              <q-icon
                name="content_copy"
                size="xs"
                color="primary"
                class="cursor-pointer"
                :disable="loading"
                @click="copyData(stream_name)"
              >
                <q-tooltip>{{ $t('copy') }}</q-tooltip>
              </q-icon>
            </template>
          </q-input>
        </div>
        <div class="settings-toggle-actions"></div>
      </div>
    </template>
  </div>

  <q-dialog v-model="show_popup">
    <q-card>
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold text-white">{{
            $t('workflow_builder_subscription')
          }}</span>
        </q-toolbar-title>
      </q-toolbar>
      <q-card-section>
        {{ $t('workflow_builder_subscription_info') }}
      </q-card-section>
      <div class="row q-pb-md">
        <f-btn
          appearance="cancel"
          class="col-6 buttons"
          @click="
            ((show_popup = false),
            (settings[bod_connection_stream_setting] = false))
          "
        >
          {{ $t('cancel') }}
        </f-btn>
        <f-btn
          class="col-6 buttons"
          @click="changeBODStreamConnectionSubscription()"
        >
          {{ $t('confirm') }}
        </f-btn>
      </div>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { debounce } from 'quasar';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull, isEmptyString } from 'src/utils/general';
import {
  authApiService,
  orgPreferenceApiService,
  userApiService,
} from 'src/services';
import { bod_connection_stream_setting } from 'src/constants';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {},
  data() {
    return {
      bod_connection_stream_setting,
      isUndefinedOrNull,
      isEmptyString,
    };
  },
  watch: {},
  mounted: function () {
    this.initView();
  },
  computed: {},
  methods: {
    async initView() {
      this.debounceSaveFunc = debounce(() => {
        this.saveSettings();
      }, 2000);

      try {
        this.settings[this.bod_connection_stream_setting] = false;
        this.loading = true;
        const response =
          await orgPreferenceApiService.getBODConnectionStreamPref();
        if (response.success === false) {
          throw response;
        }
        this.settings[this.bod_connection_stream_setting] = response.data.value;
        this.stream_name = response.data.stream_name;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async save(value: any) {
      this.loading = true;
      if (value == true) {
        this.saveSettings();
        this.show_popup = true;
      } else {
        const data = {
          org_id: userApiService.getOrgId(),
        };
        try {
          await authApiService.deleteBODStreamSubscription(data);
        } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
        } finally {
          this.loading = false;
        }
      }
      this.settings[this.bod_connection_stream_setting] = value;
      this.debounceSaveFunc();
    },

    async changeBODStreamConnectionSubscription() {
      this.show_popup = false;

      try {
        const orgId = userApiService.getOrgId();

        let subscriptionPlans = await authApiService.getSubscriptionPlans();
        subscriptionPlans = subscriptionPlans.filter(
          (plan: { key: string }) => plan.key === 'BOD_STREAM_CONNECTION',
        );

        const data = {
          org_id: orgId,
          plan_id: subscriptionPlans[0].id,
          start_date: new Date().toISOString(),
        };
        const sub = await authApiService.setBODStreamSubscription(data);

        const usageData = {
          org_id: orgId,
          app_key: 'BOD_STREAM_CONNECTION',
          token: sub.token,
        };
        authApiService.setBODSteamSubscriptionUsage(usageData);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async saveSettings() {
      try {
        this.loading = true;
        const key = this.bod_connection_stream_setting;
        const value = this.settings[this.bod_connection_stream_setting];
        const response =
          await orgPreferenceApiService.setBODConnectionStreamPref({
            key,
            value,
          });
        if (response.success === false) {
          throw response;
        }
        this.stream_name = value ? response.data.stream_name : '';
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    return {
      loading: ref(false),
      stream_name: ref(''),
      debounceSaveFunc: {} as any,
      settings: ref({} as dynamicObj),
      show_popup: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.buttons {
  margin: auto;
  max-width: 40%;
}
</style>
