<template>
  <div class="page-container page-height-limit">
    <div class="settings-page-content">

      <!-- No results message -->
      <div v-if="searchQuery && !hasAnyMatch" class="no-results-message text-center q-pa-xl">
        <q-icon name="search_off" size="48px" color="grey-5" />
        <p class="q-mt-md text-grey-6">{{ $t('no_results_found') || 'No matching settings found' }}</p>
      </div>

      <!-- Document Type Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('documentType')"
        v-model="expandedSections.documentType"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('documentType') }"
        icon="mdi:file-document-outline"
        :title="$t('document_type')"
        :subtitle="$t('document_type_configuration')"
        bodyClass=""
      >
        <WorkflowBuilder />
        <AnnotationMode />
        <ReportPage />
        <InboundEmails />
        <ModelsLabels />
        <DocScript />
        <DocScan />
        <QRExtract />
        <CustomMasterData />
        <TasksAndNotifications />
        <DOCOperator />
        <DOCNet />
        <InforACL />
        <BarcodeAssignment />
        <NegativeSignForCreditNotes />
        <SkipHybridPdfXmlExtraction />
      </DocbitsAccordionPanel>

      <!-- Shipping And Supplier Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('shippingSupplier')"
        v-model="expandedSections.shippingSupplier"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('shippingSupplier') }"
        icon="mdi:truck"
        :title="$t('shipping_and_supplier')"
        :subtitle="$t('shipping_supplier_configuration')"
        bodyClass=""
      >
        <ShippingAndSupplier />
      </DocbitsAccordionPanel>

      <!-- BOD Connection Stream Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('bodConnection')"
        v-model="expandedSections.bodConnection"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('bodConnection') }"
        icon="mdi:sync"
        :title="$t('bod_connection_stream')"
        :subtitle="$t('bod_integration_settings')"
        bodyClass=""
      >
        <BOD_ConnectionStream />
      </DocbitsAccordionPanel>

    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { useSettingStore } from 'src/store/main';
import { useAccordionSearch, type SectionSearchEntry } from 'src/utils/useAccordionSearch';
import DOCNet from '../Components/Modules/DOCNet.vue';
import DocScan from 'src/pages/Settings/Components/Modules/DocScan.vue';
import InforACL from 'src/pages/Settings/Components/Modules/InforACL.vue';
import DocScript from 'src/pages/Settings/Components/Modules/DocScript.vue';
import QRExtract from 'src/pages/Settings/Components/Modules/QR_extraction.vue';
import AnnotationMode from 'src/pages/Settings/Components/Modules/Annotation.vue';
import ModelsLabels from 'src/pages/Settings/Components/Modules/ModelsLabels.vue';
import ReportPage from 'src/pages/Settings/Components/Modules/reportPageOption.vue';
import WorkflowBuilder from 'src/pages/Settings/Components/Modules/WorkflowBuilder.vue';
import CustomMasterData from 'src/pages/Settings/Components/Modules/CustomMasterData.vue';
import TasksAndNotifications from 'src/pages/Settings/Components/Modules/TasksAndNotifications.vue';
import DOCOperator from 'src/pages/Settings/Components/Modules/DOCOperator.vue';
import InboundEmails from 'src/pages/Settings/Components/Modules/InboundEmails.vue';
import BarcodeAssignment from 'src/pages/Settings/Components/Modules/BarcodeAssignment.vue';
import ShippingAndSupplier from 'src/pages/Settings/Components/Modules/ShippingAndSupplier.vue';
import BOD_ConnectionStream from 'src/pages/Settings/Components/Modules/BOD_ConnectionStream.vue';
import NegativeSignForCreditNotes from 'src/pages/Settings/Components/Modules/NegativeSignForCreditNotes.vue';
import SkipHybridPdfXmlExtraction from 'src/pages/Settings/Components/Modules/SkipHybridPdfXmlExtraction.vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';

const SEARCH_REGISTRY: Record<string, SectionSearchEntry> = {
  documentType: {
    titleKeys: ['document_type', 'document_type_configuration'],
    childKeys: [
      'wf_workflow_builder',
      'annotation_mode',
      'show_report',
      'inbound_emails',
      'models_labels',
      'doc_script',
      'doc_scan',
      'qr_code_extraction',
      'custom_master_data',
      'tasks_and_notifications',
      'dashboard_tasks_count',
      'doc_operator',
      'doc_net',
      'idm_acl_updater',
      'barcode_assignment',
      'set_negative_sign_for_credit_notes',
      'skip_hybrid_pdf_xml_extraction',
    ],
  },
  shippingSupplier: {
    titleKeys: ['shipping_and_supplier', 'shipping_supplier_configuration'],
    childKeys: ['supplier_dashboard'],
  },
  bodConnection: {
    titleKeys: ['bod_connection_stream', 'bod_integration_settings'],
    childKeys: ['bod_connection_stream', 'stream_name'],
  },
};

const SECTION_DEFAULTS: Record<string, boolean> = {
  documentType: true,
  shippingSupplier: false,
  bodConnection: false,
};

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  watch: {
    loading_settings: {
      handler: function (newVal) {
        if (newVal) {
          this.showLoading();
        }
      },
    },
    $route() {
      this.scrollToHash();
    },
  },
  components: {
    WorkflowBuilder,
    InboundEmails,
    ModelsLabels,
    ReportPage,
    DocScript,
    DocScan,
    InforACL,
    QRExtract,
    AnnotationMode,
    TasksAndNotifications,
    CustomMasterData,
    ShippingAndSupplier,
    BOD_ConnectionStream,
    BarcodeAssignment,
    DOCOperator,
    DOCNet,
    NegativeSignForCreditNotes,
    SkipHybridPdfXmlExtraction,
    DocbitsAccordionPanel,
  },
  mounted: function () {
    this.startSettingsFetch();
    this.scrollToHash();
  },
  methods: {
    scrollToHash() {
      if (this.$route.hash) {
        this.$nextTick(() => {
          setTimeout(() => {
            const element = document.getElementById(
              this.$route.hash.substring(1),
            );
            if (element) {
              element.scrollIntoView({ behavior: 'smooth' });
            }
          }, 100);
        });
      }
    },

    onSearch(searchItem: string) {
      this.handleSearch(searchItem, this.$t);
    },
  },

  setup() {
    const settings_store = useSettingStore();
    const { startSettingsFetch, loading_settings } = settings_store;
    const accordionSearch = useAccordionSearch(SEARCH_REGISTRY, SECTION_DEFAULTS);

    return {
      startSettingsFetch,
      loading_settings,
      ...accordionSearch,
    };
  },
});
</script>

<style lang="scss" scoped>
.section-dimmed {
  opacity: 0.4;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.no-results-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 200px;
}
</style>
