<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('set_negative_sign_for_credit_notes') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[set_negative_sign_for_credit_notes]"
          @update:model-value="updateCreditNoteSettings"
        />
      </div>
    </div>
  </div>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { set_negative_sign_for_credit_notes } from 'src/constants';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: ['showSpinner'],
  components: {
    Loader,
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.hideLoading();
          this.setDefaultValues();
        } else {
          this.showLoading();
        }
      },
    },
  },
  data() {
    return {
      set_negative_sign_for_credit_notes,
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      updateSetting,
      user_settings,
      loading_settings,
    };
  },
  mounted: function () {
    this.setDefaultValues();
  },
  methods: {
    setDefaultValues() {
      if (!this.user_settings[this.set_negative_sign_for_credit_notes]) {
        this.user_settings[this.set_negative_sign_for_credit_notes] = false;
      }
    },

    async updateCreditNoteSettings(value: any) {
      this.showLoading();
      await this.updateSetting(this.set_negative_sign_for_credit_notes, value);
      this.hideLoading();
      notify.success(this.$t('MSG_SAVE'));
    },
  },
});
</script>
