<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('custom_master_data') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[custom_master_data]"
          @update:model-value="(val: any) => { updateSetting(custom_master_data, val); }"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { custom_master_data } from 'src/constants';

export default defineComponent({
  el: '#app',
    props: ['showSpinner'],
  components: {},
  data() {
    return {
      custom_master_data,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  computed: {},
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.custom_master_data]) {
        this.user_settings[this.custom_master_data] = false;
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
