<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('doc_net') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <subscription-dialog
          v-model="show_popup"
          :settings="settings"
          :settingType="docnet_setting"
          :appKey="doc_net"
          :onConfirm="handleSubscriptionConfirm"
        />
        <f-toggle size="xs"
          v-model="user_settings[docnet_setting]"
          @update:model-value="save"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore, useSubscriptionStore } from 'src/store/main';
import { docnet_setting } from 'src/constants';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
import { CONSTANTS } from 'src/constants';

export default defineComponent({
  el: '#app',
    props: ['showSpinner'],
  components: {
    subscriptionDialog,
  },
  data() {
    return {
      docnet_setting,
      settings: {} as Record<string, any>,
      stream_name: '' as string,
      activated: false as boolean,
      doc_net: CONSTANTS.doc_net,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
      show_popup: ref(false),
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.docnet_setting]) {
        this.user_settings[this.docnet_setting] = false;
      }
    },

    save(value: any) {
      if (value) {
        this.user_settings[this.docnet_setting] = false;
        this.show_popup = true;
      } else {
        this.handleSubscriptionConfirm(value);
      }
    },

    handleSubscriptionConfirm(value: any) {
      // Called from dialog after successful subscription
      // Now actually save the setting
      useSubscriptionStore().saveSubscriptionChange(
        value,
        this.doc_net,
        this.showNotification,
        this.updateSetting,
        this.showErrorToast,
        this.showSuccessToast,
      );
    },
  },
});
</script>
